/* jobId gelmediyse ya da UUID degilse akis BURADA duruyor.
   Sebebi: asagidaki HTTP dugumu bir cron ucunu cagiriyor ve gecersiz
   girdiyle bos bir kosu tetiklemek NVIDIA kotasi harcamak demek. */
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const g = $input.first().json.body || $input.first().json;
const jobId = String(g.jobId || '');
if (!UUID.test(jobId)) {
  throw new Error('gecersiz jobId: ' + jobId.slice(0, 40));
}
return [{ json: { jobId } }];

/* Uc musteri verisi dondurmuyor: yalnizca sayilar. WORKFLOW 4'e
   gidecek olan da bu. */
const r = $input.first().json;
return [{ json: {
  ok: r.ok === true,
  jobId: $('jobId doğrula').first().json.jobId,
  generated: r.generated || 0,
  errors: r.errors || {}
} }];
